def find_best(query):
    candidates=[]
    page_index=0
    page_limit=20
    min_price=0.0
    max_price=1e18
    sort_by='+price'
    while True:
        res = apis.amazon.search_products(query=query, min_price=min_price, max_price=max_price, page_index=page_index, page_limit=page_limit, sort_by=sort_by)
        if not res or (isinstance(res, dict) and 'message' in res):
            break
        if len(res)==0:
            break
        for p in res:
            name=str(p.get('name',''))
            desc=str(p.get('description',''))
            text=(name+' '+desc).lower()
            # strict: must mention face shield or just face+shield
            if ('face shield' in text) or (('face' in text) and ('shield' in text)):
                if p.get('delivery_days', math.inf) <= 4 and p.get('inventory_quantity', 0) > 0:
                    candidates.append(p)
        page_index += 1
    if not candidates:
        return None, len(candidates)
    best = sorted(candidates, key=lambda x: (x.get('price', math.inf), x.get('delivery_days', math.inf), x.get('name','')))[0]
    return best, len(candidates)

for q in ['face shield', 'face shield protective', 'clear face shield']:
